def badge_color(hue, sat, val):
    if sat == 0.0:
        return val, val, val
    i = int(hue * 6.0)
    f = (hue * 6.0) - i
    p = val * (1.0 - sat)
    q = val * (1.0 - sat * f)
    t = val * (1.0 - sat * (1.0 - f))
    i = i % 6
    if i == 0:
        return val, t, p
    if i == 1:
        return q, val, p
    if i == 2:
        return p, val, t
    if i == 3:
        return p, q, val
    if i == 4:
        return t, val, p
    return val, p, q

