def review_ratio(text, default=None):
    if text is None:
        return default
    s = text.strip()
    if not s:
        return default
    parts = s.split('/')
    if len(parts) != 2:
        return default
    try:
        num = int(parts[0])
        den = int(parts[1])
    except ValueError:
        return default
    if den == 0:
        return default
    return num / den

