def render_clock(seconds, show_tenths=False):
    if seconds < 0:
        seconds = 0.0
    whole = int(seconds)
    if not show_tenths:
        return f'{whole // 60}:{whole % 60:02d}'
    tenths = int(round((seconds - whole) * 10))
    if tenths == 10:
        whole += 1
        tenths = 0
    return f'{whole // 60}:{whole % 60:02d}.{tenths}'

