import math


def plan_runs(waiting, seats, cycle_minutes):
    if waiting <= 0:
        return 0, 0
    chairs = math.ceil(waiting / seats)
    return chairs, chairs * cycle_minutes

files.lib/chargegrid.py:
def allocate_kw(total, weights):
    if not weights:
        return []
    spread = sum(weights)
    if spread <= 0:
        return [0 for _ in weights]
    exact = [total * w / spread for w in weights]
    shares = [int(x) for x in exact]
    leftover = total - sum(shares)
    order = sorted(range(len(weights)), key=lambda i: (shares[i] - exact[i], i))
    for i in order[:leftover]:
        shares[i] += 1
    return shares

