assert plan_load(7, [('fast', 5), ('slow', 3), ('tiny', 2)]) == {'fast': 4, 'slow': 2, 'tiny': 1}
assert plan_load(0, [('x', 1), ('y', 2)]) == {'x': 0, 'y': 0}
assert plan_load(9, [('a', 2), ('b', 2), ('c', 2)]) == {'a': 3, 'b': 3, 'c': 3}
assert plan_load(5, [('idle-1', 0), ('idle-2', 0)]) == {'idle-1': 0, 'idle-2': 0}
assert sum(plan_load(11, [('m', 4), ('n', 4), ('o', 3)]).values()) == 11

files.lib/csvkit.py:
def format_row(values, sep=','):
    cells = []
    for value in values:
        text = str(value)
        if sep in text or '"' in text or '\n' in text:
            text = '"' + text.replace('"', '""') + '"'
        cells.append(text)
    return sep.join(cells)

