files.lib/pickeroute.py:
def plan_picks(order, slot_map):
    picks = []
    for sku, qty in order.items():
        if qty <= 0:
            continue
        aisle, shelf = slot_map.get(sku, ('ZZ', '00'))
        picks.append({'sku': sku, 'qty': qty, 'aisle': aisle, 'shelf': shelf})
    picks.sort(key=lambda p: (p['aisle'], p['shelf'], p['sku']))
    return picks

